//! Decoding tests on small WAV files generated by the test.

mod common;

use common::{SAMPLE_RATE, assert_close, render_frames, wait_until_decoded, write_wav};
use dubplate_engine::{DeckId, EngineError, decode_file, offline_engine};

fn sine(frame: usize, frequency: f32, sample_rate: u32) -> f32 {
    0.5 * (std::f32::consts::TAU * frequency * frame as f32 / sample_rate as f32).sin()
}

#[test]
fn decodes_a_stereo_wav_to_the_same_samples() {
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("stereo.wav");
    let sample_rate = 44_100;
    let frame_count = 22_050;
    let samples: Vec<f32> = (0..frame_count)
        .flat_map(|frame| {
            let value = sine(frame, 440.0, sample_rate);
            [value, -value]
        })
        .collect();
    write_wav(&path, &samples, 2, sample_rate);

    let track = decode_file(&path).unwrap();
    wait_until_decoded(&track);
    assert_eq!(track.sample_rate(), sample_rate);
    assert_eq!(track.source_channels(), 2);
    assert_eq!(track.decoded_frames(), frame_count);
    assert_close(track.duration_seconds().unwrap(), 0.5, 1e-9);
    for frame in [0, 1, 100, 12_345, frame_count - 1] {
        let [left, right] = track.frame(frame).unwrap();
        let expected = samples[frame * 2];
        assert_close(f64::from(left), f64::from(expected), 1.0 / 32_767.0);
        assert_close(f64::from(right), f64::from(-expected), 1.0 / 32_767.0);
    }
    assert_eq!(track.frame(frame_count), None);
}

#[test]
fn plays_a_mono_wav_on_both_sides() {
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("mono.wav");
    let samples = vec![0.25; 4800];
    write_wav(&path, &samples, 1, 48_000);

    let track = decode_file(&path).unwrap();
    wait_until_decoded(&track);
    assert_eq!(track.source_channels(), 1);
    let [left, right] = track.frame(2400).unwrap();
    assert_close(f64::from(left), 0.25, 1e-4);
    assert_eq!(left, right);
}

#[test]
fn a_decoded_file_plays_on_a_deck() {
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("deck.wav");
    let samples = vec![0.5; 48_000 * 2 * 2];
    write_wav(&path, &samples, 2, 48_000);

    let (mut controller, mut renderer) = offline_engine(SAMPLE_RATE);
    let track = controller.load_file(DeckId::A, &path).unwrap();
    wait_until_decoded(&track);
    controller.set_crossfader(0.0).unwrap();
    controller.play(DeckId::A).unwrap();
    let output = render_frames(&mut renderer, 48_000, 480);
    assert_close(f64::from(output[output.len() - 1]), 0.5, 1e-4);
    assert_close(controller.deck_state(DeckId::A).position_seconds, 1.0, 1e-9);
    assert_eq!(controller.stats().starved_callbacks, 0);
}

#[test]
fn a_file_that_is_not_audio_is_rejected() {
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("notes.wav");
    std::fs::write(&path, "these are not samples").unwrap();
    assert!(matches!(
        decode_file(&path),
        Err(EngineError::Decode { .. })
    ));
}

#[test]
fn a_missing_file_is_reported() {
    let directory = tempfile::tempdir().unwrap();
    assert!(matches!(
        decode_file(directory.path().join("missing.mp3")),
        Err(EngineError::OpenFile { .. })
    ));
}
